fn total(count: u32, cents: u32) -> u32 {
    count * cents
}

fn main() {
    let count = 3;
    let mut cents = 275;
    cents += 25;
    println!("{} cents", total(count, cents));
}

fn main() {
    for score in 0..=5 {
        let label = match score {
            0 => "none",
            1..=3 => "some",
            _ => "many",
        };
        println!("{score}: {label}");
    }
}

fn first_word(text: &str) -> Option<&str> {
    text.split_whitespace().next()
}

fn main() {
    let mut title = String::from("Ion notes");
    println!("{:?}", first_word(&title));
    title.push_str(" today");
    println!("{title}");
}

use std::collections::HashMap;

fn main() {
    let labels = vec!["ion", "learn", "ion"];
    let mut counts = HashMap::new();
    for label in labels.iter().copied() {
        *counts.entry(label).or_insert(0) += 1;
    }
    println!("{:?}", counts.get("ion"));
}

struct Topic { name: String }
enum Progress { Pending, Complete(u8) }

trait Label {
    fn label(&self) -> &str;
}

impl Label for Topic {
    fn label(&self) -> &str { &self.name }
}

fn main() {
    let topic = Topic { name: String::from("Ownership") };
    for state in [Progress::Pending, Progress::Complete(9)] {
        match state {
            Progress::Pending => println!("{} is pending", topic.label()),
            Progress::Complete(score) => println!("{}: {score}", topic.label()),
        }
    }
}

fn double(text: &str) -> Result<i32, std::num::ParseIntError> {
    let value: i32 = text.trim().parse()?;
    Ok(value.saturating_mul(2))
}

fn main() {
    match double(" 21 ") {
        Ok(value) => println!("{value}"),
        Err(error) => eprintln!("Invalid count: {error}"),
    }
    assert_eq!(double("3").ok(), Some(6));
}
